import {bookPage,bookFeature,bookGuidance} from '../src/cookbook-pages.mjs';
import {collectionBooks,collectionBookPage} from '../src/collection-books.mjs';
import fs from 'node:fs/promises';
import path from 'node:path';
import { site,products,programmes,courses,recipes,journal } from '../src/data.mjs';
import {buildExperience} from '../src/experience.mjs';
import {buildAccountPages} from '../src/account-pages.mjs';
import { money,cadenceName,unitPrice } from '../src/commerce.mjs';
const membership=products.find(p=>p.id==='nufi-membership');
const root=path.resolve(import.meta.dirname,'..'),out=path.join(root,'dist');
await fs.rm(out,{recursive:true,force:true});await fs.mkdir(out,{recursive:true});
await fs.cp(path.join(root,'public'),out,{recursive:true});
await fs.copyFile(path.join(root,'src/data.mjs'),path.join(out,'data.mjs'));
await fs.copyFile(path.join(root,'src/collection-books.mjs'),path.join(out,'collection-books.mjs'));
await fs.copyFile(path.join(root,'src/commerce.mjs'),path.join(out,'commerce.mjs'));
let sprite=await fs.readFile(path.join(root,'src/sprite.html'),'utf8');
const extra={book:'<path d="M12 6c-3-3-7-3-10-2v15c4-1 7 0 10 2 3-2 6-3 10-2V4c-3-1-7-1-10 2Zm0 0v15"/>',repeat:'<path d="M4 8h13l-3-3M20 16H7l3 3M20 8v3M4 16v-3"/>',truck:'<path d="M3 5h12v12H3zM15 10h4l3 4v3h-7"/><circle cx="7" cy="19" r="2"/><circle cx="18" cy="19" r="2"/>',shield:'<path d="M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6Z"/><path d="m8 12 3 3 5-6"/>',plus:'<path d="M12 4v16M4 12h16"/>',minus:'<path d="M4 12h16"/>',drop:'<path d="M12 2S5 10 5 15a7 7 0 0 0 14 0c0-5-7-13-7-13Z"/>',house:'<path d="m3 10 9-7 9 7v11H3ZM9 21v-8h6v8"/>',run:'<circle cx="15" cy="4" r="2"/><path d="m6 11 5-3 4 4 5 1M11 8l-2 8 6 3 1 4M9 16l-5 6"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-8Z"/>',moon:'<path d="M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12Z"/>',play:'<circle cx="12" cy="12" r="10"/><path d="m10 8 6 4-6 4Z"/>',mail:'<rect x="2" y="5" width="20" height="15" rx="2"/><path d="m2 6 10 7L22 6"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6M12 7h.01"/>'};
sprite=sprite.replace('</defs>',Object.entries(extra).map(([k,v])=>`<symbol id="i-${k}" viewBox="0 0 24 24">${v}</symbol>`).join('')+'</defs>');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<svg aria-hidden="true"><use href="#i-${n}"/></svg>`;
const link=(text,to,cls='')=>`<a href="${to}" class="button ${cls}">${text} ${icon('arrow')}</a>`;
const eyebrow=t=>`<p class="eyebrow">${t}</p>`;
const note=t=>`<p class="handnote">${t}</p>`;
const notice=(text='This is a working website preview. Catalogue details and prices are examples, not a live offer.')=>`<p class="quiet-note">${icon('info')}${text}</p>`;
const nav=[['Home','/'],['NUFI+','/nufi/'],['Programmes','/programmes/'],['Recipes','/recipes/'],['Courses','/courses/'],['Shop','/shop/'],['About','/about/'],['Knowledge Centre','/knowledge-centre/']];
function brand(){return `<a class="brand" href="/" aria-label="Nutrition.Fitness home"><span class="wordmark"><strong>nutrition.</strong><span>fitness</span><sup>®</sup></span><span class="brand-tagline">${site.strapline}</span></a>`;}
function header(current){const active=url=>url==='/'?current==='/':current.startsWith(url);return `<div class="preview-bar"><span>Design preview</span> Example catalogue & prices. No live orders. <a href="/site-map/">Explore the pages ${icon('arrow')}</a></div><header class="site-header">${brand()}<nav class="desktop-nav" aria-label="Main navigation">${nav.map(([t,u])=>`<a href="${u}" ${active(u)?'class="is-active" aria-current="page"':''}>${t}</a>`).join('')}</nav><div class="header-actions"><a class="icon-button" href="/search/" aria-label="Search the website">${icon('search')}</a><a class="icon-button account-button" href="/account/" aria-label="Your account">${icon('user')}</a><a class="icon-button bag-button" href="/basket/" aria-label="Your basket">${icon('bag')}<span class="bag-count" hidden>0</span></a><a class="button button-small header-cta" href="/get-started/">Get started ${icon('arrow')}</a><button type="button" class="icon-button menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="mobile-nav">${icon('menu')}</button></div></header><nav class="mobile-nav" id="mobile-nav" hidden aria-label="Mobile navigation">${nav.map(([t,u])=>`<a href="${u}">${t}</a>`).join('')}<a href="/search/">Search the website</a><a href="/subscriptions/">Build your subscription</a><a href="/help/">A little help</a>${link('Get started','/get-started/')}</nav>`;}
function footer(){return `<footer class="new-footer"><div class="footer-main">${brand()}<p>Made for people who want to be fitter.<br>Including people who don’t particularly like fitness.</p><img src="/assets/note-see-you.webp" width="86" height="70" loading="lazy" alt="See you there."></div><div class="footer-links"><div><strong>Less complicated</strong><a href="/nufi/">Meet NUFI+</a><a href="/coaches/">Jeff & Steff</a><a href="/programmes/">Programmes</a><a href="/courses/">Courses</a><a href="/community/">Community</a></div><div><strong>Good things</strong><a href="/shop/">Shop everything</a><a href="/shop/?category=powders">Plain powders</a><a href="/shop/?category=shots">Flavour shots</a><a href="/subscriptions/">Build a subscription</a><a href="/recipe-books/">Recipe books</a></div><div><strong>Real people</strong><a href="/about/">Our story</a><a href="/knowledge-centre/">Knowledge Centre</a><a href="/journal/">A useful read</a><a href="/trust/">What we stand for</a><a href="/help/">Help & FAQs</a><a href="/contact/">Get in touch</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Nutrition.Fitness · Website preview</span><div><a href="/privacy/">Privacy</a><a href="/terms/">Terms</a><a href="/delivery/">Delivery & returns</a><a href="/site-map/">Site map</a><button type="button" class="text-button" data-clear-preview>Reset preview data</button></div></div></footer>`;}
const routes=[];
async function page(url,title,body,{description='Fitness and nutrition for real life. Programmes, meals, shopping and support, brought together by Nutrition.Fitness.',type=''}={}){
 if(routes.some(r=>r.url===url))throw new Error('Duplicate route: '+url);
 const target=url==='/'?'index.html':url==='/404/'?'404.html':url.slice(1)+'index.html';
 const html=`<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#faf6ef"><meta name="robots" content="noindex,nofollow"><meta name="description" content="${esc(description)}"><title>${esc(title)} | Nutrition.Fitness</title><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;650;700;750;800;850;900&family=Kalam:wght@400&display=swap" rel="stylesheet"><link rel="stylesheet" href="/base.css"><link rel="stylesheet" href="/site.css"><link rel="stylesheet" href="/food.css"><link rel="stylesheet" href="/cookbook-collection.css"><link rel="stylesheet" href="/knowledge-navigation.css"><script type="module" src="/site.mjs"></script><script type="module" src="/food.mjs"></script></head><body data-page="${type||url}"><a href="#main" class="skip-link">Skip to content</a>${sprite}<div class="site-shell">${header(url)}<main id="main">${body}</main>${footer()}</div><div role="status" aria-live="polite" class="notification" hidden></div><noscript><div class="noscript-note">The pages work without JavaScript. The basket, filters and preview account need JavaScript to be enabled.</div></noscript></body></html>`;
 await fs.mkdir(path.dirname(path.join(out,target)),{recursive:true});await fs.writeFile(path.join(out,target),html);
 if(url!='/404/')routes.push({url,title,file:target});
}
const intro=(over,title,lead,extra='')=>`<section class="page-intro">${eyebrow(over)}<h1>${title}</h1><p class="lead">${lead}</p>${extra}</section>`;
function art(p,cls=''){
 if(p.art==='collection-book')return `<div class="product-art actual-book-art ${cls}"><img src="${esc(p.image)}" alt="${esc(p.name)} — actual book cover" loading="lazy"></div>`;
 if(p.art==='published-book')return `<div class="product-art actual-book-art ${cls}"><img src="${p.image}" alt="The High Protein Kitchen — actual cover of the 100-recipe edition" loading="lazy"></div>`;
 if(['pouch','bottle'].includes(p.art))return `<div class="product-art product-photo ${cls}"><img src="/assets/products/${p.id}.webp" alt="${esc(p.name)} — packaging preview" loading="lazy"></div>`;
 if(p.art==='pouch') return `<div class="product-art ${p.color} ${cls}" aria-label="${esc(p.name)} packaging concept"><div class="pouch"><span class="seal"></span><span class="pouch-brand">nutrition.fitness</span><strong>${esc(p.label).replace(/\n/g,'<br>')}</strong><span class="pouch-plain">unflavoured</span><em>${p.id==='creatine'?'No dramatic name.':'Plain on purpose.'}</em><small>${p.size}</small><span class="pouch-base"></span></div></div>`;
 if(p.art==='bottle')return `<div class="product-art ${p.color} ${cls}" aria-label="${esc(p.name)} pipette bottle concept"><div class="shot-bottle"><div class="dropper-top"></div><div class="dropper-ring"></div><div class="bottle-body"><div class="bottle-label"><span>nutrition.fitness</span><strong>${esc(p.label)}</strong><span>flavour shot</span><small>A change of taste.</small></div></div></div></div>`;
 if(p.art==='book')return `<div class="product-art ${p.color} ${cls}"><div class="book-art"><small>nutrition.fitness</small><strong>${p.name.replace('The ','').replace('High Protein','High protein<br>')}</strong><img src="/assets/${p.image}.webp" alt="Food photograph for the ${esc(p.name)} cover concept" loading="lazy"><em>${p.quip}</em></div></div>`;
 return `<div class="product-art aqua ${cls}"><strong class="nufi-big">NUFI<span>+</span></strong></div>`;
}
function productCard(p){return `<article class="product-card" data-category="${p.category}" data-search="${esc((p.name+' '+p.quip).toLowerCase())}" data-price="${p.price}"><a href="/shop/${p.id}/" class="product-image-link">${art(p)}<span class="corner-label">${p.art==='published-book'?'100 recipes · Launching 1 November':p.category==='books'?`${p.recipeCount} recipes · Coming soon`:p.category==='shots'?'Flavour, sold separately':'Plain base'}</span></a><div class="product-card-copy"><div class="card-name-row"><h3><a href="/shop/${p.id}/">${p.name}</a></h3><strong>${money(p.price)}</strong></div><p>${p.quip}</p><div class="product-meta"><span>${p.size}</span><a href="/shop/${p.id}/" aria-label="${p.category==='books'?'Explore':'Choose options for'} ${esc(p.name)}">${p.category==='books'?'Explore the book':'Choose options'} ${icon('arrow')}</a></div></div></article>`;}
function programmeCard(p){return `<article class="programme-card" data-category="${['Home','Gym','Outdoors'].filter(c=>p.place.toLowerCase().includes(c.toLowerCase())).join('|')}" data-search="${esc((p.name+' '+p.description+' '+p.place).toLowerCase())}"><a href="/programmes/${p.slug}/" class="programme-art ${p.color}"><span>${p.tag}</span><strong>${p.name}<i>.</i></strong>${icon(p.icon)}<small>${p.quip}</small></a><div class="programme-info"><div class="programme-tags"><span>${p.weeks} weeks</span><span>${p.sessions} sessions / week</span><span>${p.level}</span></div><h3><a href="/programmes/${p.slug}/">${p.title}</a></h3><p>${p.description}</p><a class="arrow-link" href="/programmes/${p.slug}/">Meet the programme ${icon('arrow')}</a></div></article>`;}
function courseCard(c){return `<article class="course-card" data-category="${c.category}" data-search="${esc((c.name+' '+c.short+' '+c.category).toLowerCase())}"><a class="course-art ${c.color}" href="/courses/${c.slug}/">${icon(c.icon)}<span>${c.category}</span><strong>${c.name}</strong><small>${c.modules.length} proposed modules</small></a><div class="course-copy"><h3><a href="/courses/${c.slug}/">${c.short}</a></h3><p>${c.intro}</p><a class="arrow-link" href="/courses/${c.slug}/">Have a look inside ${icon('arrow')}</a></div></article>`;}
function recipeCard(r){return `<article class="recipe-card" data-category="${r.category}" data-search="${esc((r.name+' '+r.ingredients.join(' ')).toLowerCase())}"><a href="/recipes/${r.slug}/"><img src="/assets/${r.image}.webp" alt="${esc(r.name)} concept food photograph" loading="lazy"><div class="recipe-card-text"><span class="eyebrow">${r.category} · Recipe idea</span><h3>${r.name}</h3><p>${r.note}</p><span class="arrow-link">See the idea ${icon('arrow')}</span></div></a></article>`;}
const faq=items=>`<div class="faq-list">${items.map(([q,a])=>`<details><summary>${q}<span>${icon('plus')}</span></summary><p>${a}</p></details>`).join('')}</div>`;
const steps=items=>`<div class="steps-grid">${items.map(([t,p],i)=>`<div><span class="step-number">0${i+1}</span><h3>${t}</h3><p>${p}</p></div>`).join('')}</div>`;
const band=(title,desc,to,label)=>`<section class="cta-band aqua"><div><h2>${title}</h2><p>${desc}</p></div>${link(label,to)}</section>`;
const filter=(items,placeholder='Find something useful',sort=false)=>`<div class="filter-bar"><div class="filter-chips" role="group" aria-label="Filter by category">${items.map((x,i)=>`<button class="filter-chip ${i===0?'active':''}" data-filter="${x[1]}" aria-pressed="${i===0}">${x[0]}</button>`).join('')}</div><label class="search-field">${icon('search')}<input type="search" data-catalogue-search placeholder="${placeholder}" aria-label="${placeholder}"></label>${sort?'<label class="sort-field"><span class="sr-only">Sort products</span><select data-sort><option value="featured">Featured</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="name">Name: A to Z</option></select></label>':''}</div><p class="filter-status" role="status" aria-live="polite"></p>`;

// HOME — the approved composition, now with real page destinations.
await page('/','Getting fit. Less complicated.',await fs.readFile(path.join(root,'src/home.html'),'utf8'),{type:'home'});

// NUFI landing page.
await page('/nufi/','Meet NUFI+',`<section class="mast-split nufi-mast"><div>${eyebrow('NUFI+ · your everyday plan')}<h1>You have a life.<br><span class="plum">We have a plan.</span></h1><p class="lead">Your workouts, food, shopping and progress, in one place. Instead of seventeen tabs and a vague sense of guilt.</p>${link('Start my plan','/get-started/')}<p class="microcopy">Jeff would like to point out that you still do the workouts.</p></div><div class="nufi-phone"><img src="/assets/phone-in-hand.webp" alt="Example NUFI dashboard on a phone" width="466" height="487"></div></section><section class="content-section"><div class="section-heading"><div>${eyebrow('Here is the plan')}<h2>Less working it out.<br>More getting on with it.</h2></div><p>Real life comes included.<br>Perfect weeks are not required.</p></div>${steps([['Tell us about you.','Your goals, food preferences and schedule. No plan for an imaginary person with unlimited free time.'],['Meet your plan.','Programmes, meal planning, shopping lists and progress, brought together.'],['Follow today.','One clear next step. If Tuesday has other ideas, review and adjust.']])}</section><section class="feature-split cream" id="meal-planning"><div>${eyebrow('Food, minus the daily debate')}<h2>Dinner should not require<br><span class="plum">a project manager.</span></h2><p>Plan meals around your preferences. See the shopping in one list. Log what you actually eat and keep the plan honest.</p><ul class="tick-list"><li>${icon('check')}Your nutrition targets come from onboarding.</li><li>${icon('check')}Planned and eaten food stay separate, then reconcile.</li><li>${icon('check')}Protein and the day’s remaining targets stay visible.</li></ul><a class="arrow-link" href="/recipes/">Take a look at the food ${icon('arrow')}</a></div><img class="food-square" src="/assets/chicken-bowl.webp" alt="Chicken, grains and vegetables in a bowl" loading="lazy"></section><section class="content-section"><div class="section-heading"><h2>The useful bits.<br>Not a feature Olympics.</h2></div><div class="benefit-grid">${[['dumbbell','Programmes that fit','Train at home or at the gym, with a programme that notices your calendar.'],['cart','Shopping, sorted','A list that comes from your meals. Not a separate Sunday-night admin job.'],['book','Learn the why','Practical courses that help you use the system, rather than collect more information.'],['people','Someone in your corner','Choose Jeff or Steff, your AI coach. Helpful first. Funny when the moment is right.']].map(([i,t,p])=>`<article>${icon(i)}<h3>${t}</h3><p>${p}</p></article>`).join('')}</div></section><section class="coaches-lite aqua"><div><h2>Meet the brains.<br><span class="plum">Both of them.</span></h2><p>Jeff and Steff are AI coaches. Same tools, different personalities. No pretending a chatbot is a clinician.</p>${link('Meet Jeff & Steff','/coaches/')}</div><div class="duo-portraits"><img src="/assets/jeff.webp" alt="Jeff, an AI coach" loading="lazy"><img src="/assets/steff.webp" alt="Steff, an AI coach" loading="lazy"></div></section><section class="content-section" id="pricing"><div class="section-heading"><div>${eyebrow('Membership options')}<h2>One system.<br>Less juggling.</h2></div><p>Supplements are optional and sold separately.<br>Good food is still very much invited.</p></div><div class="pricing-grid">${[['month','Monthly',money(membership.price),'per month','A little less commitment.'],['year','Annual',money(membership.annualPrice),'per year','For the longer game.']].map(([c,t,price,period,desc])=>`<article class="price-card ${c==='year'?'aqua':''}"><span class="pill-label">Example price</span><h3>${t}</h3><p>${desc}</p><div class="price-large">${price}<small>${period}</small></div><ul class="tick-list"><li>${icon('check')}Programmes and meal planning</li><li>${icon('check')}Shopping lists and progress</li><li>${icon('check')}Courses and your chosen AI coach</li></ul>${link('Choose '+t.toLowerCase(),'/get-started/?billing='+c)}<small>Illustrative pricing. No membership is activated here.</small></article>`).join('')}</div>${notice('These are proposed membership options for design review, not approved launch prices. The live NUFI service is not connected.')}</section><section class="content-section slim"><h2>A few fair questions.</h2>${faq([['Is this just an AI chat app?','No. NUFI is the programme and meal-planning system. Jeff and Steff help you use it. Courses support the experience; they are not the whole product.'],['Do I have to buy supplements?','No. The shop is optional. Plain protein and flavour shots are separate products, not a condition of using NUFI.'],['Do I get a human personal trainer?','Do not assume one-to-one coaching is included. Human support, community access and any live sessions must be confirmed in the final offer. Jeff and Steff are AI.'],['Can I try this website?','Yes. You can explore the onboarding outline, build a basket and preview a subscription. None of that creates a real account, payment or personalised health plan.']])}</section>`,{type:'nufi'});

// Account-aware recipes, planner, shopping, and the modular programme/course system.
await buildExperience({page});
await buildAccountPages({page});

// Courses.

// Recipe ideas and books.
await page('/recipe-books/','The recipe-book collection',`<div class="page-container">${intro('Good food, in book form','Proper food.<br><span class="plum">Eight good places to start.</span>','Meet The High Protein Kitchen and seven new Nutrition.Fitness recipe books. Breakfasts, everyday meals, big nights in, air fryer favourites, snacks, smoothies and plenty of plants.')}<div class="catalogue-grid product-grid">${products.filter(p=>p.category==='books').map(productCard).join('')}</div><p class="food-small">The seven new books are coming soon as digital PDFs, with the original recipe photographs. Prices and purchase details will be announced before orders open.</p></div>`);

await page('/shop/high-protein-kitchen/','The High Protein Kitchen — 100 recipes for real life',bookPage(),{type:'book-product'});
for(const book of collectionBooks)await page(`/shop/${book.id}/`,book.title,collectionBookPage(book),{type:'book-product',description:`${book.title}: ${book.recipeCount} recipes in a ${book.pageCount}-page digital book from Nutrition.Fitness. ${book.coverLine} Coming soon; price to be announced.`});
await page('/recipes/cooking-and-storage/','Cooking and storage — from The High Protein Kitchen',bookGuidance(),{type:'book-guidance'});
// SHOP.
await page('/shop/','Plain protein, powders & flavour shots',`<div class="page-container"><section class="shop-mast"><div>${eyebrow('The not-overcomplicated shop')}<h1>Plain protein.<br><span class="plum">Very good company.</span></h1><p class="lead">Choose your powder. Add a flavour shot. Change your mind about the flavour tomorrow.</p><p class="shop-joke">A kilo of strawberry is quite a commitment to Tuesday’s mood.</p>${link('Build my box','/subscriptions/')}<a class="inline-link" href="#products">Just browsing? Carry on ↓</a></div><div class="shop-arrangement cream">${art(products[0],'hero-pack')}${art(products.find(p=>p.id==='shot-strawberry'),'hero-shot-one')}${art(products.find(p=>p.id==='shot-chocolate'),'hero-shot-two')}<span class="arrangement-note handnote">Keep the base.<br>Change the plot.</span><span class="concept-caption">Nutrition.Fitness · packaging previews</span></div></section><div class="shop-principles"><span>${icon('drop')}Flavour sold separately</span><span>${icon('repeat')}Buy once or build a subscription</span><span>${icon('shield')}You choose what goes in</span></div>${bookFeature()}<section id="products">${filter([['Everything','all'],['Plain powders','powders'],['Flavour shots','shots'],['Recipe books','books']],'Search the shop',true)}<div class="catalogue-grid product-grid" data-filter-grid>${products.filter(p=>p.category!=='membership').map(productCard).join('')}</div></section>${notice('All prices, pack sizes and delivery terms are examples for review. The range is proposed, not confirmed stock. Product information must be approved before sale.')}${band('Same powder. A new plot twist.','Build a regular box of plain powder and separate flavour shots. Nothing added behind your back.','/subscriptions/','Build my subscription')}</div>`,{type:'shop'});
for(const p of products.filter(p=>p.category!=='membership'&&p.category!=='books'))await page(`/shop/${p.id}/`,p.name,`<div class="page-container"><a class="back-link" href="/shop/">← Back to the shop</a><section class="product-detail" data-product-id="${p.id}"><div class="product-gallery">${art(p,'large-art')}<span class="concept-caption">Packaging preview · final label subject to approval</span></div><div class="product-buybox">${eyebrow(p.category==='shots'?'Flavour shots · sold separately':p.category==='books'?'The recipe-book collection':'Plain powders · your base')}<h1>${p.name}</h1><p class="product-quip">${p.quip}</p><p>${p.description}</p><div class="detail-price"><strong data-unit-price>${money(p.price)}</strong><span>${p.size} · example price</span></div><form id="product-form"><fieldset class="purchase-options"><legend>How would you like it?</legend><label class="purchase-option"><input type="radio" name="purchase" value="once" checked><span><strong>Buy once</strong><small>One order. No encore.</small></span><b>${money(p.price)}</b></label>${p.recurring?`<label class="purchase-option"><input type="radio" name="purchase" value="subscription"><span><strong>Subscribe & save ${site.subscriptionDiscount}%</strong><small>A regular delivery you choose.</small></span><b>${money(unitPrice({id:p.id,qty:1,mode:'subscription',cadence:'4w'}))}</b></label><div class="subscription-cadence" hidden><label for="cadence">Delivery frequency</label><select id="cadence" name="cadence"><option value="4w">Every 4 weeks</option><option value="8w">Every 8 weeks</option></select><p>Repeated charge shown in your basket. These are preview terms.</p></div>`:''}</fieldset>${p.category==='powders'&&p.id!=='creatine'?`<details class="flavour-addons"><summary>Add a little personality? <span>Optional flavour shots</span></summary><p>Your powder stays plain. These are separate bottles, added as one-off items.</p><div class="addon-options">${products.filter(x=>x.category==='shots').map(s=>`<label><input type="checkbox" name="shot" value="${s.id}"><span>${s.short}</span><b>${money(s.price)}</b></label>`).join('')}</div><a class="arrow-link" href="/subscriptions/">Want the shots on repeat too? Build a box ${icon('arrow')}</a></details>`:''}<div class="add-to-bag-row"><label class="quantity-field"><span>Quantity</span><input type="number" name="quantity" min="1" max="20" value="1" required aria-label="Quantity"></label><button type="submit" class="button">Add to my basket ${icon('bag')}</button></div><p class="form-error" role="alert" hidden></p><p class="purchase-summary" aria-live="polite"></p></form><p class="small-print">Example prices. No live payment. <a href="/delivery/">Preview delivery information</a>.</p></div></section><section class="content-section two-column"><div><h2>The useful details.</h2><ul class="tick-list">${p.details.map(x=>`<li>${icon('check')}${x}</li>`).join('')}</ul></div><div class="inset-card cream"><h3>The important, unfunny bit.</h3><p>${p.caution}</p><p>Humour belongs on the pack. Guesswork does not belong in the ingredients.</p></div></section><section class="content-section"><div class="section-heading"><h2>${p.category==='powders'?'A few possible plot twists.':p.category==='shots'?'Meet the plain half of the partnership.':'More food for thought.'}</h2><a class="arrow-link" href="/shop/">Back to the shop ${icon('arrow')}</a></div><div class="catalogue-grid product-grid">${products.filter(x=>p.category==='powders'?x.category==='shots':p.category==='shots'?x.category==='powders':x.category==='books'&&x.id!==p.id).slice(0,3).map(productCard).join('')}</div></section></div>`,{type:'product'});

// Full-screen subscription builder.
await page('/subscriptions/','Build your subscription',`<div class="page-container">${intro('Your cupboard. Your rules.','A regular delivery.<br><span class="plum">Not a flavour life sentence.</span>','Choose a plain powder, add separate shots and set the pace. We keep the decisions visible. You keep the final say.')}<form id="box-form" class="builder-layout"><div><section class="builder-section"><div class="builder-heading"><span>01</span><div><h2>Start with your base.</h2><p>One plain powder. No flavour secretly mixed in.</p></div></div><div class="base-choices">${products.filter(p=>p.category==='powders').map(p=>`<label class="base-choice"><input type="radio" name="base" value="${p.id}" ${p.id==='plain-whey'?'checked':''}>${art(p)}<strong>${p.name}</strong><span>${p.size} · ${money(unitPrice({id:p.id,qty:1,mode:'subscription',cadence:'4w'}))} / delivery</span></label>`).join('')}</div><label class="inline-field">Tubs per delivery <input type="number" id="base-qty" min="1" max="6" value="1"></label></section><section class="builder-section"><div class="builder-heading"><span>02</span><div><h2>Pick your plot twists.</h2><p>Optional flavour shots. Add as many or as few different flavours as you need.</p></div></div><div class="shot-choices">${products.filter(p=>p.category==='shots').map(p=>`<div class="shot-choice ${p.color}"><label><input type="checkbox" name="box-shot" value="${p.id}"><strong>${p.short}</strong><span>${money(unitPrice({id:p.id,qty:1,mode:'subscription',cadence:'4w'}))} / bottle / delivery</span></label><label class="shot-qty-label">Bottles <input type="number" min="1" max="6" value="1" data-shot-quantity="${p.id}" aria-label="${p.short} bottles per delivery"></label></div>`).join('')}</div></section><section class="builder-section"><div class="builder-heading"><span>03</span><div><h2>Set your pace.</h2><p>Four weeks and a calendar month are different. We mean four weeks.</p></div></div><div class="cadence-options"><label><input type="radio" name="box-cadence" value="4w" checked><strong>Every 4 weeks</strong><span>Every 28 days</span></label><label><input type="radio" name="box-cadence" value="8w"><strong>Every 8 weeks</strong><span>Every 56 days</span></label></div><div class="nufi-addon"><label><input type="checkbox" id="add-nufi"><span><strong>Add NUFI+ to the picture?</strong><small>Example ${money(membership.price)} per calendar month. Digital membership renews separately from your box.</small></span></label><a href="/nufi/" class="arrow-link">What is NUFI+? ${icon('arrow')}</a></div></section></div><aside class="builder-summary"><div class="sticky-summary cream"><span class="pill-label">Your box · preview</span><h2>Here’s the plan.</h2><div id="box-summary" aria-live="polite"></div><p class="small-print">Example ${site.subscriptionDiscount}% subscription saving. Delivery ${money(site.shipping.fee)} below ${money(site.shipping.freeOver)}, free from ${money(site.shipping.freeOver)}. All terms and prices need launch approval.</p><p class="form-error" role="alert" hidden></p><button type="submit" class="button">Add this box ${icon('arrow')}</button><p class="microcopy">No payment or subscription is created at this step.</p></div></aside></form></div>`,{type:'subscriptions'});

await page('/basket/','Your basket',`<div class="page-container compact-page">${intro('The useful things you picked','Your basket.<br><span class="plum">No mysterious extras.</span>','One-off purchases and repeat deliveries, clearly separated.')}<div id="basket-content"></div><noscript><p>Enable JavaScript to view the basket.</p></noscript></div>`,{type:'basket'});
await page('/checkout/','Review your order',`<div class="page-container compact-page"><a class="back-link" href="/basket/">← Back to your basket</a>${intro('Checkout preview','A proper look.<br><span class="plum">Before anything happens.</span>','This is a demonstration. No card details, no payment and no actual delivery.')}<div id="checkout-content"></div></div>`,{type:'checkout'});
await page('/checkout/thanks/','Your preview order',`<div class="page-container compact-page"><div id="order-content"></div></div>`,{type:'thanks'});

// Coach pages and local onboarding / account preview.
await page('/coaches/','Meet Jeff & Steff',`<div class="page-container">${intro('The people-shaped part of the software','Helpful. Human in tone.<br><span class="plum">Honest about being AI.</span>','Meet Jeff and Steff. Same coaching tools, different personalities. Choose either, whatever your gender.')}<div class="coach-profile-grid">${[['Jeff','aqua','Helpful. Straight-talking. Occasionally a bit too pleased with himself.','“I’ll help with the plan. I’m still terrible at doing your squats for you.”'],['Steff','blush','Warm. Sharp. Supportive. And well aware that real life happens.','“A busy Tuesday isn’t a personality flaw. Let’s plan around it.”']].map(([n,c,d,q])=>`<article class="coach-profile ${c}"><img src="/assets/${n.toLowerCase()}.webp" alt="${n}, a fictional AI coach"><div><span class="pill-label">AI coach</span><h2>${n}.</h2><p>${d}</p><blockquote>${q}</blockquote><button type="button" class="button" data-pick-coach="${n}">Choose ${n} ${icon('check')}</button><p class="coach-choice-status" aria-live="polite"></p></div></article>`).join('')}</div><section class="content-section slim"><h2>A sense of humour.<br>And some common sense.</h2>${faq([['Do they judge me if I go off plan?','No. Accountability should not turn into shame. The joke is about the situation, not your body, appetite or worth.'],['Are they human coaches?','No. Jeff and Steff are clearly labelled AI coaches. They are not doctors, dietitians or a replacement for appropriate professional support.'],['Will they change things without asking?','Your choices stay authoritative. Suggestions and changes need to be clear and traceable. No pretending to read your diary or silently rearranging your life.'],['Can I chat to them here?','This website saves your coach choice locally. Live AI conversation and access to your actual NUFI data are not connected in this build.']])}</section>${band('Your plan. Your personality preference.','Choose your starting point, then take one thing at a time.','/get-started/','Start my plan')}</div>`,{type:'coaches'});
await page('/get-started/','Start with you',`<div class="page-container onboarding-page">${intro('A small start','Let’s start with you.<br><span class="plum">Not the imaginary version.</span>','A short preview of the first steps. No full health assessment or nutrition targets are created here.')}<form id="onboarding-form" class="onboarding-card cream"><div class="step-indicator" aria-label="Onboarding progress"><span class="active">1 · Your life</span><span>2 · Your plan</span><span>3 · Your coach</span></div><section class="onboarding-step" data-step="0"><h2>What would you like a hand with?</h2><label class="field-label" for="first-name">First name <span>(optional, saved on this device only)</span></label><input class="text-input" id="first-name" name="name" maxlength="40" autocomplete="given-name" placeholder="What should we call you?"><label class="field-label" for="goal">Your main goal</label><select id="goal" name="goal" required><option value="">Choose one to start</option><option>Feel fitter</option><option>Build strength</option><option>Make food easier</option><option>Build a routine</option></select><label class="field-label" for="place">Where would you usually train?</label><select id="place" name="place"><option>At home</option><option>At the gym</option><option>A bit of both</option><option>Outdoors</option></select></section><section class="onboarding-step" data-step="1" hidden><h2>A plan that notices your calendar.</h2><label class="field-label" for="programme">A programme to explore</label><select name="programme" id="programme">${programmes.map(p=>`<option value="${p.slug}">${p.name} · ${p.tag}</option>`).join('')}</select><label class="field-label" for="time">Time you could set aside</label><select id="time" name="time"><option>About 20 minutes</option><option>About 30 minutes</option><option>About 45 minutes</option></select><label class="field-label" for="billing">A membership option to review</label><select id="billing" name="billing"><option value="month">Monthly · example ${money(membership.price)}</option><option value="year">Annual · example ${money(membership.annualPrice)}</option></select><p class="quiet-note">This choice does not start a paid membership.</p></section><section class="onboarding-step" data-step="2" hidden><h2>Who is in your corner?</h2><div class="onboarding-coaches">${['Jeff','Steff'].map((n,i)=>`<label class="${i?'blush':'aqua'}"><input type="radio" name="coach" value="${n}" ${i===0?'checked':''}><img src="/assets/${n.toLowerCase()}.webp" alt="${n}, AI coach"><strong>${n}</strong><span>${i?'Warm. Sharp. On your side.':'Helpful. Quite pleased with himself.'}</span></label>`).join('')}</div><p>Both are AI. Neither can empty the dishwasher. Expectations are important.</p></section><p class="form-error" hidden role="alert"></p><div class="onboarding-actions"><button type="button" class="text-button" id="previous-step" hidden>← Back</button><button type="button" class="button" id="next-step">Next ${icon('arrow')}</button><button type="submit" class="button" id="finish-onboarding" hidden>See my plan outline ${icon('arrow')}</button></div></form></div>`,{type:'onboarding'});

// About, community and help.
await page('/about/','Our story',`<div class="page-container"><section class="mast-split"><div>${eyebrow('Hello. We are Nutrition.Fitness.')}<h1>Serious about you.<br><span class="plum">Less serious about ourselves.</span></h1><p class="lead">We are here to make getting fitter feel less like homework. Because you have quite enough of that sort of thing.</p></div><img class="about-photo" src="/assets/more-good-days.webp" alt="A parent and child enjoying time outdoors"></section><section class="content-section two-column"><div><h2>It started with a fairly ordinary wish.</h2><p>James wanted to get fitter, feel better and have a plan that fitted his life. He liked the idea of the result. He was considerably less excited about organising all the bits that came before it.</p><p>The training. The food. The recipes. The shopping. The constant working out what to do next.</p><p>So the question became: what if those things actually worked together?</p></div><div class="inset-card blush"><h2>We do the thinking.<br>You do the doing.</h2>${note('Seems fair.')}<p>That is the idea behind NUFI+. One system for your programmes, meals, shopping and progress, with Jeff or Steff in your corner.</p><p>Not a promise that software does the work for you. Just a promise to stop making the planning harder than it needs to be.</p></div></section><section class="content-section"><h2>What we stand for.</h2><div class="values-grid">${[['Real life is allowed.','Kids, work, meals out and awkward Tuesdays. The plan needs to live in your world.'],['Useful beats impressive.','A clear next step is worth more than a clever feature nobody understands.'],['No guilt trips.','Accountability is helpful. Making people feel small is not.'],['Tell the truth.','Clear product information, honest prices and no mystery miracle powders.'],['Make people feel known.','Remember the useful things. Notice progress. Put care into the ordinary moments.'],['Have a laugh.','Take the work seriously. Do not make every protein shake sound like a military briefing.']].map(([t,p])=>`<article><h3>${t}</h3><p>${p}</p></article>`).join('')}</div></section>${band('Fitness that supports your life.','Not fitness that moves in and takes over the spare room.','/nufi/','Meet NUFI+')}</div>`);
await page('/community/','A little company helps',`<div class="page-container">${intro('Real support. No performance required.','You do not need<br><span class="plum">to do the awkward bit alone.</span>','The community direction: questions welcomed, small wins noticed and no one being made to feel bad for having a life.')}<div class="feature-split cream"><img class="about-photo" src="/assets/more-good-days.webp" alt="Time outdoors with family"><div><h2>People, not before-and-after photos.</h2><p>A place for practical questions, useful encouragement and the occasional “well, that did not go to plan”.</p><ul class="tick-list"><li>${icon('check')}Respectful conversation</li><li>${icon('check')}No body shaming or food policing</li><li>${icon('check')}Clear distinction between AI and human support</li><li>${icon('check')}Moderation and escalation for serious concerns</li></ul>${link('Explore NUFI+','/nufi/')}</div></div>${notice('Community access, moderation, expert Q&As and challenge schedules are proposed features. A live group is not connected and no event timetable is being promised.')}</div>`);
await page('/trust/','The boring bits that matter',`<div class="page-container slim">${intro('Trust should have something behind it.','A little less hype.<br><span class="plum">A lot more straight answers.</span>','We would rather explain what is true than fill this page with stars we have not earned.')}<div class="values-grid">${[['Honest product information.','Ingredients, allergens and nutrition must match the final product. A nice label is not a substitute for verification.'],['Clear AI disclosure.','Jeff and Steff are AI coaches. They are not presented as real staff or qualified clinicians.'],['Your choices stay yours.','Quantities, preferences and overrides should be respected. No silent “optimisation”.'],['No invented reviews.','This preview does not use fabricated testimonials, customer counts or trust ratings.'],['Visible subscription terms.','Show the contents, renewal interval and charge before commitment. No pre-ticked subscription consent.'],['Own the mistakes.','Clear explanations and practical help. Humour is not an excuse to dodge a serious problem.']].map(([t,p])=>`<article><h3>${t}</h3><p>${p}</p></article>`).join('')}</div>${band('Have a question?','A reasonable thing to do before parting with your money.','/help/','Find an answer')}</div>`);
const helpFAQs=[['What is NUFI+?','The core training and nutrition system: programmes, meal planning, shopping lists and progress, supported by courses and your chosen AI coach.'],['Are the powders flavoured?','The proposed range uses plain powders. Flavour shots are separate bottles, so you choose what goes with your base. Final formulas and labels still need approval.'],['Can I buy without subscribing?','Yes. The shop defaults to a one-off purchase. You must actively choose a recurring option.'],['How often does a subscription repeat?','The box builder offers 4-week or 8-week delivery intervals. NUFI membership uses calendar-month or annual billing. These are clearly separated in the basket.'],['Can I pause, cancel or change a delivery?','The account preview demonstrates those controls locally. It does not change a real subscription. Production cut-off dates, billing terms and account integration must be approved and connected before launch.'],['Where are the course videos?','The courses currently contain reading lessons and saved completion checklists for each programme base. They are not video courses. Detailed workout delivery belongs in the connected NUFI app.'],['Are the prices final?','No. They are example prices used to demonstrate the shop and totals. No live orders are taken.'],['Is my information saved?','Guest plans and food logs are saved in this browser. Configured, verified accounts can synchronise their own workspace. The account screen states the connection status. Quiz reservations go to the configured signup service and CRM. See Privacy for details.'],['Can I get help from a human?','A production support destination has not been supplied. The contact page includes a request builder you can copy, but it does not silently send your information anywhere.']];
await page('/help/','A little help',`<div class="page-container slim">${intro('The question department','Good questions.<br><span class="plum">Straight answers.</span>','No need to spend your afternoon arguing with a search box.')}${faq(helpFAQs)}${band('Still scratching your head?','Put your question in one place, ready for the support team.','/contact/','Get in touch')}</div>`);
await page('/contact/','Get in touch',`<div class="page-container compact-page">${intro('Hello from the other side of the website.','Let’s sort it.<br><span class="plum">Preferably without a saga.</span>','Tell us what you need a hand with. In this preview, you can prepare and copy a support request. It is not sent anywhere.')}<form id="contact-form" class="contact-card cream"><label class="field-label" for="topic">What is it about?</label><select id="topic" name="topic"><option>NUFI+ and programmes</option><option>Food and meal planning</option><option>Products and flavour shots</option><option>Subscriptions and billing</option><option>Something else</option></select><label class="field-label" for="message">Your message</label><textarea id="message" name="message" rows="6" maxlength="3000" required placeholder="The useful details. No essay required."></textarea><p class="small-print">Please do not include payment details or sensitive health information.</p><button class="button" type="submit">Prepare my message ${icon('arrow')}</button><div id="contact-result" hidden><label class="field-label" for="prepared-message">Your request, ready to copy</label><textarea id="prepared-message" readonly rows="7"></textarea><button type="button" class="button button-light" data-copy-message>Copy message</button><p>No support address or sending service has been connected yet. This message has not been sent.</p></div></form></div>`,{type:'contact'});

await page('/journal/','A useful read',`<div class="page-container">${intro('The journal','A little food for thought.<br><span class="plum">No motivational shouting.</span>','Notes on the system we are building, the choices behind it and making room for real life.')}<div class="catalogue-grid journal-grid">${journal.map(j=>`<article class="journal-card"><a href="/journal/${j.slug}/"><img src="/assets/${j.image}.webp" alt="${j.category} concept illustration" loading="lazy"><div>${eyebrow(j.category)}<h2>${j.title}</h2><p>${j.intro}</p><span class="arrow-link">Read the note ${icon('arrow')}</span></div></a></article>`).join('')}</div></div>`);
for(const j of journal)await page(`/journal/${j.slug}/`,j.title,`<article class="page-container article-page"><a href="/journal/" class="back-link">← All notes</a>${intro(j.category,j.title,j.intro)}<img class="article-image" src="/assets/${j.image}.webp" alt="${j.category}"><div class="article-copy">${j.paragraphs.map(p=>`<p>${p}</p>`).join('')}</div>${link('Meet NUFI+','/nufi/')}</article>`);
await page('/search/','Find something useful',`<div class="page-container compact-page">${intro('Less hunting around.','What are you after?','Programmes, plain powders, courses or the bit about Jeff.')}<form id="site-search-form" class="large-search"><label class="sr-only" for="site-search">Search the whole website</label>${icon('search')}<input type="search" name="q" id="site-search" placeholder="Try “flavour shots” or “meal planning”" autofocus><button type="submit" class="button">Search</button></form><p id="search-status" aria-live="polite"></p><div id="search-results"></div></div>`,{type:'search'});

// Real preview-disclosure pages, not fabricated live business policies.
await page('/privacy/','Privacy and your choices',`<div class="page-container legal-page">${intro('The unfunny but important bit.','Your data.<br><span class="plum">Your choices.</span>','This explains how this build handles information. The live service still requires an owner-approved privacy notice and contact details before account registration is enabled.')}<h2>Browsing and guest planning</h2><p>You can browse recipes and use the meal planner without an account. Guest meal plans, food logs, recipe edits, favourites, course-reading progress and the targets you explicitly enter are saved in this browser. Clearing site data removes that local copy. Export a backup from the planner before clearing it.</p><h2>Saving to an account</h2><p>Once secure account services are configured, verified members can synchronise their planner workspace to their own account. Account workspaces are separated by user. Importing a guest plan is an explicit action, not a silent merge. Login uses an emailed one-time code; secure, HttpOnly cookies hold the login session.</p><h2>Programme finder and GoHighLevel</h2><p>Submitting the quiz reservation sends your name, email, programme recommendation, quiz answers and selected communication preference to the configured signup service and GoHighLevel CRM. We keep a delivery record so a temporary CRM problem does not lose a confirmed reservation. Meal plans, food logs and nutrition targets are not copied into the CRM by this build.</p><h2>Optional marketing</h2><p>Receiving tips, news and offers is optional and separate from reserving your free app month. The checkbox is not preselected. Leaving it unticked does not withdraw an existing subscription; use the unsubscribe controls on existing marketing messages or the live service’s contact process. A new request must not override existing suppression settings.</p><h2>Security and external services</h2><p>When configured, Supabase handles account verification and account data, Cloudflare Turnstile checks signup abuse, and GoHighLevel holds CRM contact records. Hosting handles ordinary website requests. The site requests fonts from Google Fonts and may display credited external photographs. No advertising pixel or marketing analytics is installed by this build.</p><h2>What is not live by default</h2><p>Shop prices and packaging are still previews. The ordinary basket and checkout are demonstrations, not live payments or orders. There is no live AI chat. Account, CRM and app activation functions cannot report success without their required services and release settings.</p><h2>Backups and removal</h2><p>Planner backups can contain personal information; keep them private. Planner/account screens identify whether a workspace is saved in this browser or synchronised. The footer reset affects the older shopping preview, not your meal-planning workspace. Clear meal-planning data only after exporting anything you need.</p><h2>Required before live registration</h2><p>The owner must publish the final controller identity and contact route, lawful bases, retention periods, deletion/request procedures, processor details and treatment of any health-related information. These operational details are not invented in this build. Account activation must remain disabled until this review and the real service tests are complete.</p></div>`);
await page('/terms/','Preview terms',`<div class="page-container legal-page">${intro('No small-print gymnastics.','This is a preview.<br>Not a live offer.','These pages demonstrate a proposed website, catalogue and shopping experience.')}<h2>Purchases and membership</h2><p>Prices, product sizes, course structures and delivery rules are illustrative. Demo checkout does not create a real order, take payment, activate NUFI membership or deliver an ebook.</p><h2>Subscriptions</h2><p>The preview shows the intended distinction between a one-off purchase and a recurring order. The proposed 4-week and 8-week box schedules differ from monthly or annual NUFI billing. Final renewal, cancellation, refund and delivery terms require approval before trading.</p><h2>Content</h2><p>Product formulas, allergens, recipe methods, nutritional values, course lessons and detailed exercise programming must be verified and connected. Do not use concept content as personal medical, dietary or exercise advice.</p><h2>Live terms are still required</h2><p>The trading entity, contact details, product terms, delivery commitments, cancellation rights, digital-content permissions, consumer rights and applicable policies must be reviewed for the actual business before launch.</p></div>`);
await page('/delivery/','Delivery & returns preview',`<div class="page-container legal-page">${intro('The getting-it-to-you bit.','Delivery, without<br><span class="plum">the surprise ending.</span>','The basket uses the following example rules for testing. They are not approved delivery promises.')}<div class="inset-card cream"><h2>Example UK delivery</h2><p>${money(site.shipping.fee)} for physical merchandise below ${money(site.shipping.freeOver)}. Free delivery from ${money(site.shipping.freeOver)}. Digital-only baskets have no delivery charge. No delivery date or service-level guarantee is being offered in this build.</p><p>Each recurring delivery group is quoted separately. A one-off item does not count towards the free-delivery threshold on future subscription renewals.</p></div><h2>Returns and cancellations</h2><p>A final returns policy has not been supplied. Product-specific conditions, digital-content cancellation permissions and consumer rights must be reviewed before accepting orders. The demo account controls do not cancel real payments or change real deliveries.</p><h2>What happens in the preview?</h2><p>You receive an on-screen demonstration summary. Nothing is dispatched. Which does at least make losing the parcel quite difficult.</p></div>`);
await page('/payment-test/','Test checkout return',`<div class="page-container compact-page">${intro('Developer test only','Back from test checkout.<br><span class="plum">Nothing is being dispatched.</span>','A return URL is not proof of a successful payment. This page does not activate membership, fulfil an order or store payment status.')}<div class="inset-card cream"><h2>Verify on the server.</h2><p>Use Stripe’s test dashboard or a server-side retrieval of the Checkout Session to verify the session. A production system must use verified, idempotent webhooks for fulfilment and entitlement changes.</p><p>No live payment keys are accepted by the optional test adapter included in this build.</p>${link('Back to the preview shop','/shop/')}</div></div>`);
await page('/404/','That page has wandered off',`<div class="page-container empty-state">${eyebrow('404 · not where we left it')}<h1>Well, this is awkward.</h1><p>That page has wandered off. Jeff is looking very busy and not helping.</p>${link('Back to familiar territory','/')}<a class="inline-link" href="/search/">Search the website</a></div>`);
const grouped=[['Knowledge Centre',[{url:'/knowledge-centre/',title:'Knowledge Centre'}]],['Start here',routes.filter(r=>['/','/nufi/','/programmes/','/courses/','/recipes/','/recipe-books/','/shop/','/subscriptions/'].includes(r.url))],['Programmes',routes.filter(r=>/^\/programmes\/.+/.test(r.url))],['Courses',routes.filter(r=>/^\/courses\/.+/.test(r.url))],['Shop products',routes.filter(r=>/^\/shop\/.+/.test(r.url))],['Food & journal',routes.filter(r=>/^\/(recipes|journal)\/.+/.test(r.url))],['Journey & supporting pages',routes.filter(r=>!['/','/nufi/','/programmes/','/courses/','/recipes/','/recipe-books/','/shop/','/subscriptions/'].includes(r.url)&&!/^\/(programmes|courses|shop|recipes|journal)\/.+/.test(r.url))]];
await page('/site-map/','Every page, in one place',`<div class="page-container">${intro('For you and the developers.','Everything has<br><span class="plum">somewhere to go.</span>','A full page index for reviewing the website, shop and subscription journey.')}<div class="site-map-grid">${grouped.map(([t,rs])=>`<section><h2>${t}</h2>${rs.map(r=>`<a href="${r.url}">${r.title}${icon('arrow')}</a>`).join('')}</section>`).join('')}</div><div class="inset-card cream"><h2>What is not live?</h2><p>Real accounts, lesson media, live AI, payment collection, fulfilment, subscription renewals and final policy documents. The interactions on this website are clearly labelled demonstrations. The source package contains the integration notes.</p></div></div>`);
